SET NOCOUNT ON; SET XACT_ABORT ON;
IF DB_NAME() <> N'TTSmart_Operational_V1_Test' OR NOT EXISTS(SELECT 1 FROM dbo.SchemaVersions WHERE ModuleCode=N'Operational' AND MigrationNumber=3) THROW 58400,N'Thiếu tiền điều kiện.',1;
IF EXISTS(SELECT 1 FROM dbo.SchemaVersions WHERE ModuleCode=N'Operational' AND MigrationNumber=4 AND ScriptChecksum='$(ScriptChecksum)') RETURN;
IF EXISTS(SELECT 1 FROM dbo.SchemaVersions WHERE ModuleCode=N'Operational' AND MigrationNumber=4) THROW 58401,N'Checksum không khớp.',1;
BEGIN TRANSACTION;
DECLARE @OperationalMigrationLockResult int;
EXEC @OperationalMigrationLockResult = sys.sp_getapplock @Resource=N'TTSmart.Operational.V1.Baseline', @LockMode=N'Exclusive', @LockOwner=N'Transaction', @LockTimeout=60000;
IF @OperationalMigrationLockResult < 0 THROW 58490,N'Không lấy được application lock Operational v1.',1;
IF EXISTS(SELECT 1 FROM dbo.SchemaVersions WHERE ModuleCode=N'Operational' AND MigrationNumber=4 AND ScriptChecksum='$(ScriptChecksum)') BEGIN COMMIT; RETURN; END;
IF EXISTS(SELECT 1 FROM dbo.SchemaVersions WHERE ModuleCode=N'Operational' AND MigrationNumber=4) THROW 58401,N'Checksum không khớp.',1;
CREATE TABLE dbo.Brands (BrandId uniqueidentifier NOT NULL CONSTRAINT PK_Brands PRIMARY KEY, PublicId char(24) COLLATE Latin1_General_100_BIN2 NOT NULL, Name nvarchar(200) NOT NULL, Version int NOT NULL CONSTRAINT DF_Brands_Version DEFAULT 0, RowVersion rowversion NOT NULL, CONSTRAINT UQ_Brands_PublicId UNIQUE(PublicId), CONSTRAINT CK_Brands_PublicId CHECK(PublicId NOT LIKE '%[^0-9a-f]%' AND LEN(PublicId)=24), CONSTRAINT CK_Brands_Version CHECK(Version>=0));
CREATE TABLE dbo.ProductTypes (ProductTypeId uniqueidentifier NOT NULL CONSTRAINT PK_ProductTypes PRIMARY KEY, PublicId char(24) COLLATE Latin1_General_100_BIN2 NOT NULL, Name nvarchar(200) NOT NULL, Icon nvarchar(2000) NULL, SourceCreatedAtUtc datetime2(7) NULL, SourceUpdatedAtUtc datetime2(7) NULL, Version int NOT NULL CONSTRAINT DF_ProductTypes_Version DEFAULT 0, RowVersion rowversion NOT NULL, CONSTRAINT UQ_ProductTypes_PublicId UNIQUE(PublicId), CONSTRAINT CK_ProductTypes_PublicId CHECK(PublicId NOT LIKE '%[^0-9a-f]%' AND LEN(PublicId)=24), CONSTRAINT CK_ProductTypes_Version CHECK(Version>=0));
CREATE TABLE dbo.Categories (CategoryId uniqueidentifier NOT NULL CONSTRAINT PK_Categories PRIMARY KEY, PublicId char(24) COLLATE Latin1_General_100_BIN2 NOT NULL, Name nvarchar(200) NOT NULL, ImageUrl nvarchar(2000) NULL, SourceCreatedAtUtc datetime2(7) NULL, SourceUpdatedAtUtc datetime2(7) NULL, Version int NOT NULL CONSTRAINT DF_Categories_Version DEFAULT 0, RowVersion rowversion NOT NULL, CONSTRAINT UQ_Categories_PublicId UNIQUE(PublicId), CONSTRAINT CK_Categories_PublicId CHECK(PublicId NOT LIKE '%[^0-9a-f]%' AND LEN(PublicId)=24), CONSTRAINT CK_Categories_Version CHECK(Version>=0));
CREATE TABLE dbo.CategoryValues (CategoryValueId uniqueidentifier NOT NULL CONSTRAINT PK_CategoryValues PRIMARY KEY, CategoryId uniqueidentifier NOT NULL, PublicId char(24) COLLATE Latin1_General_100_BIN2 NOT NULL, Name nvarchar(200) NOT NULL, Version int NOT NULL CONSTRAINT DF_CategoryValues_Version DEFAULT 0, RowVersion rowversion NOT NULL, CONSTRAINT FK_CategoryValues_Category FOREIGN KEY(CategoryId) REFERENCES dbo.Categories(CategoryId), CONSTRAINT UQ_CategoryValues_Category_Id UNIQUE(CategoryId,CategoryValueId), CONSTRAINT UQ_CategoryValues_PublicId UNIQUE(PublicId), CONSTRAINT CK_CategoryValues_PublicId CHECK(PublicId NOT LIKE '%[^0-9a-f]%' AND LEN(PublicId)=24), CONSTRAINT CK_CategoryValues_Version CHECK(Version>=0));
CREATE TABLE dbo.Units (UnitId uniqueidentifier NOT NULL CONSTRAINT PK_Units PRIMARY KEY, PublicId char(24) COLLATE Latin1_General_100_BIN2 NOT NULL, Name nvarchar(100) NOT NULL, DecimalScale tinyint NOT NULL CONSTRAINT DF_Units_Scale DEFAULT 0, Version int NOT NULL CONSTRAINT DF_Units_Version DEFAULT 0, RowVersion rowversion NOT NULL, CONSTRAINT UQ_Units_PublicId UNIQUE(PublicId), CONSTRAINT CK_Units_PublicId CHECK(PublicId NOT LIKE '%[^0-9a-f]%' AND LEN(PublicId)=24), CONSTRAINT CK_Units_Scale CHECK(DecimalScale BETWEEN 0 AND 6), CONSTRAINT CK_Units_Version CHECK(Version>=0));
CREATE TABLE dbo.ProductOptions (ProductOptionId uniqueidentifier NOT NULL CONSTRAINT PK_ProductOptions PRIMARY KEY, PublicId char(24) COLLATE Latin1_General_100_BIN2 NOT NULL, OptionType nvarchar(30) NOT NULL, Value nvarchar(200) NOT NULL, Version int NOT NULL CONSTRAINT DF_ProductOptions_Version DEFAULT 0, RowVersion rowversion NOT NULL, CONSTRAINT UQ_ProductOptions_PublicId UNIQUE(PublicId), CONSTRAINT CK_ProductOptions_PublicId CHECK(PublicId NOT LIKE '%[^0-9a-f]%' AND LEN(PublicId)=24), CONSTRAINT CK_ProductOptions_Version CHECK(Version>=0));
CREATE TABLE dbo.Products (ProductId uniqueidentifier NOT NULL CONSTRAINT PK_Products PRIMARY KEY, PublicId char(24) COLLATE Latin1_General_100_BIN2 NOT NULL, BrandId uniqueidentifier NULL, ProductTypeId uniqueidentifier NULL, CategoryId uniqueidentifier NULL, CategoryValueId uniqueidentifier NULL, Code nvarchar(120) NULL, Name nvarchar(300) NOT NULL, NameUnsigned nvarchar(300) NULL, Description nvarchar(max) NULL, Solution nvarchar(max) NULL, Features nvarchar(max) NULL, OperatingMethod nvarchar(max) NULL, Advantages nvarchar(max) NULL, Specifications nvarchar(max) NULL, TechnicalInformation nvarchar(max) NULL, WarrantyInformation nvarchar(max) NULL, Notes nvarchar(max) NULL, IsAdjusted bit NOT NULL CONSTRAINT DF_Products_Adjusted DEFAULT 1, IsVisible bit NOT NULL CONSTRAINT DF_Products_Visible DEFAULT 1, IsFeatured bit NOT NULL CONSTRAINT DF_Products_Featured DEFAULT 0, IsActive bit NOT NULL CONSTRAINT DF_Products_Active DEFAULT 1, PurchaseCount bigint NULL, TotalRating decimal(19,6) NULL, ReviewCount bigint NULL, AverageReviews decimal(9,4) NULL, VatRate decimal(19,4) NULL, LegacyVatRaw nvarchar(100) NULL, DataStatus nvarchar(20) NOT NULL CONSTRAINT DF_Products_DataStatus DEFAULT N'Valid', Version int NOT NULL CONSTRAINT DF_Products_Version DEFAULT 0, SourceCreatedAtUtc datetime2(7) NULL, SourceUpdatedAtUtc datetime2(7) NULL, MigratedAtUtc datetime2(7) NULL, CreatedAtUtc datetime2(7) NULL, UpdatedAtUtc datetime2(7) NULL, RowVersion rowversion NOT NULL, CONSTRAINT FK_Products_Brand FOREIGN KEY(BrandId) REFERENCES dbo.Brands(BrandId), CONSTRAINT FK_Products_Type FOREIGN KEY(ProductTypeId) REFERENCES dbo.ProductTypes(ProductTypeId), CONSTRAINT FK_Products_Category FOREIGN KEY(CategoryId) REFERENCES dbo.Categories(CategoryId), CONSTRAINT FK_Products_CategoryValue FOREIGN KEY(CategoryId,CategoryValueId) REFERENCES dbo.CategoryValues(CategoryId,CategoryValueId), CONSTRAINT UQ_Products_PublicId UNIQUE(PublicId), CONSTRAINT CK_Products_PublicId CHECK(PublicId NOT LIKE '%[^0-9a-f]%' AND LEN(PublicId)=24), CONSTRAINT CK_Products_Vat CHECK(VatRate IS NULL OR VatRate BETWEEN 0 AND 100), CONSTRAINT CK_Products_Ratings CHECK((PurchaseCount IS NULL OR PurchaseCount>=0) AND (TotalRating IS NULL OR TotalRating>=0) AND (ReviewCount IS NULL OR ReviewCount>=0) AND (AverageReviews IS NULL OR AverageReviews BETWEEN 0 AND 5)), CONSTRAINT CK_Products_DataStatus CHECK(DataStatus IN(N'Valid',N'Incomplete',N'Archived')), CONSTRAINT CK_Products_Version CHECK(Version>=0));
CREATE INDEX IX_Products_Code ON dbo.Products(Code);
CREATE TABLE dbo.ProductVariants (ProductVariantId uniqueidentifier NOT NULL CONSTRAINT PK_ProductVariants PRIMARY KEY, PublicId char(24) COLLATE Latin1_General_100_BIN2 NOT NULL, ProductId uniqueidentifier NOT NULL, Position int NOT NULL, ImageUrl nvarchar(2000) NULL, Color nvarchar(100) NULL, Shape nvarchar(100) NULL, Frame nvarchar(100) NULL, ButtonCount nvarchar(100) NULL, Note nvarchar(2000) NULL, AttributesJson nvarchar(max) NULL, SalePrice decimal(19,4) NULL, SalePriceRaw nvarchar(100) NULL, ImportPrice decimal(19,4) NULL, ImportPriceRaw nvarchar(100) NULL, Earn decimal(19,4) NULL, EarnRaw nvarchar(100) NULL, ProfitPercent decimal(19,4) NULL, DataStatus nvarchar(20) NOT NULL CONSTRAINT DF_ProductVariants_DataStatus DEFAULT N'Valid', Version int NOT NULL CONSTRAINT DF_ProductVariants_Version DEFAULT 0, RowVersion rowversion NOT NULL, CONSTRAINT FK_ProductVariants_Product FOREIGN KEY(ProductId) REFERENCES dbo.Products(ProductId), CONSTRAINT UQ_ProductVariants_Product_Id UNIQUE(ProductId,ProductVariantId), CONSTRAINT UQ_ProductVariants_PublicId UNIQUE(PublicId), CONSTRAINT CK_ProductVariants_PublicId CHECK(PublicId NOT LIKE '%[^0-9a-f]%' AND LEN(PublicId)=24), CONSTRAINT CK_ProductVariants_Position CHECK(Position>=0), CONSTRAINT CK_ProductVariants_Prices CHECK((SalePrice IS NULL OR SalePrice>=0) AND (ImportPrice IS NULL OR ImportPrice>=0) AND (Earn IS NULL OR Earn>=0)), CONSTRAINT CK_ProductVariants_DataStatus CHECK(DataStatus IN(N'Valid',N'Incomplete',N'Archived')), CONSTRAINT CK_ProductVariants_Version CHECK(Version>=0));
CREATE TABLE dbo.ProductFiles (ProductFileId uniqueidentifier NOT NULL CONSTRAINT PK_ProductFiles PRIMARY KEY, PublicId char(24) COLLATE Latin1_General_100_BIN2 NOT NULL, ProductId uniqueidentifier NOT NULL, FileId uniqueidentifier NULL, ExternalUrl nvarchar(2000) NULL, Label nvarchar(300) NULL, FileType nvarchar(50) NULL, SourcePath nvarchar(1000) NULL, SortOrder int NOT NULL CONSTRAINT DF_ProductFiles_Sort DEFAULT 0, Version int NOT NULL CONSTRAINT DF_ProductFiles_Version DEFAULT 0, RowVersion rowversion NOT NULL, CONSTRAINT FK_ProductFiles_Product FOREIGN KEY(ProductId) REFERENCES dbo.Products(ProductId), CONSTRAINT FK_ProductFiles_File FOREIGN KEY(FileId) REFERENCES dbo.Files(FileId), CONSTRAINT UQ_ProductFiles_PublicId UNIQUE(PublicId), CONSTRAINT CK_ProductFiles_PublicId CHECK(PublicId NOT LIKE '%[^0-9a-f]%' AND LEN(PublicId)=24), CONSTRAINT CK_ProductFiles_Reference CHECK((FileId IS NULL AND ExternalUrl IS NOT NULL) OR (FileId IS NOT NULL AND ExternalUrl IS NULL)), CONSTRAINT CK_ProductFiles_Version CHECK(Version>=0));
CREATE TABLE dbo.ProductVariantFiles (ProductVariantFileId uniqueidentifier NOT NULL CONSTRAINT PK_ProductVariantFiles PRIMARY KEY, PublicId char(24) COLLATE Latin1_General_100_BIN2 NOT NULL, ProductVariantId uniqueidentifier NOT NULL, FileId uniqueidentifier NULL, ExternalUrl nvarchar(2000) NULL, Label nvarchar(300) NULL, FileType nvarchar(50) NULL, SourcePath nvarchar(1000) NULL, SortOrder int NOT NULL CONSTRAINT DF_ProductVariantFiles_Sort DEFAULT 0, CONSTRAINT FK_ProductVariantFiles_Variant FOREIGN KEY(ProductVariantId) REFERENCES dbo.ProductVariants(ProductVariantId), CONSTRAINT FK_ProductVariantFiles_File FOREIGN KEY(FileId) REFERENCES dbo.Files(FileId), CONSTRAINT UQ_ProductVariantFiles_PublicId UNIQUE(PublicId), CONSTRAINT CK_ProductVariantFiles_PublicId CHECK(PublicId NOT LIKE '%[^0-9a-f]%' AND LEN(PublicId)=24), CONSTRAINT CK_ProductVariantFiles_Reference CHECK((FileId IS NULL AND ExternalUrl IS NOT NULL) OR (FileId IS NOT NULL AND ExternalUrl IS NULL)));
CREATE TABLE dbo.ProductReviews (ProductReviewId uniqueidentifier NOT NULL CONSTRAINT PK_ProductReviews PRIMARY KEY, PublicId char(24) COLLATE Latin1_General_100_BIN2 NOT NULL, ProductId uniqueidentifier NOT NULL, ReviewerUserId uniqueidentifier NULL, ReviewerName nvarchar(200) NULL, ReviewerEmail nvarchar(320) NULL, Rating decimal(4,2) NOT NULL, Comment nvarchar(4000) NULL, Version int NOT NULL CONSTRAINT DF_ProductReviews_Version DEFAULT 0, CreatedAtUtc datetime2(7) NOT NULL CONSTRAINT DF_ProductReviews_Created DEFAULT SYSUTCDATETIME(), RowVersion rowversion NOT NULL, CONSTRAINT FK_ProductReviews_Product FOREIGN KEY(ProductId) REFERENCES dbo.Products(ProductId), CONSTRAINT FK_ProductReviews_Reviewer FOREIGN KEY(ReviewerUserId) REFERENCES dbo.Users(UserId), CONSTRAINT UQ_ProductReviews_PublicId UNIQUE(PublicId), CONSTRAINT CK_ProductReviews_PublicId CHECK(PublicId NOT LIKE '%[^0-9a-f]%' AND LEN(PublicId)=24), CONSTRAINT CK_ProductReviews_Rating CHECK(Rating BETWEEN 1 AND 5), CONSTRAINT CK_ProductReviews_Version CHECK(Version>=0));
ALTER TABLE dbo.Products DROP CONSTRAINT CK_Products_Ratings;
ALTER TABLE dbo.Products ALTER COLUMN PurchaseCount bigint NULL;
ALTER TABLE dbo.Products ALTER COLUMN ReviewCount bigint NULL;
ALTER TABLE dbo.Products ADD CONSTRAINT CK_Products_Ratings CHECK((PurchaseCount IS NULL OR PurchaseCount>=0) AND (TotalRating IS NULL OR TotalRating>=0) AND (ReviewCount IS NULL OR ReviewCount>=0) AND (AverageReviews IS NULL OR AverageReviews BETWEEN 0 AND 5));
CREATE UNIQUE INDEX UX_Products_Code_NotNull ON dbo.Products(Code) WHERE Code IS NOT NULL;
CREATE UNIQUE INDEX UX_ProductVariants_Product_Position ON dbo.ProductVariants(ProductId,Position);
INSERT dbo.SchemaVersions SELECT NEWID(),N'Operational',4,N'004_CreateCatalogTables.sql','$(ScriptChecksum)',SYSUTCDATETIME(),ORIGINAL_LOGIN(); COMMIT;
GO
